<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientAllowedAudiencesAudienceAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientAllowedAudiencesAudienceAccessor trait.
 *
 * Covers null default, string/VO assignment via withAudience,
 * getAudience/audience accessors, and isAudienceChanged with/without original.
 */
class TrustedClientAllowedAudiencesAudienceAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withAudience creates a new instance with the Audience set
     * from a string value, and getAudience returns the primitive string.
     */
    public function testWithAudienceFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientAllowedAudiencesAudienceAccessorUnitTest();

        // Act
        $result = $holder->withAudience('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getAudience());
    }
    /**
     * Asserts that withaudience has access to the value object
     * from a string value, and getAudience returns the primitive string.
     */
    public function testWithAudienceFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientAllowedAudiencesAudienceAccessorUnitTest();

        // Act
        $result = $holder->withAudience('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->audience()->value());
    }
    public function testChangedAudience(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientAllowedAudiencesAudienceAccessorUnitTest()->withAudience('one');
        $original = $holder->withAudience('one');
        $same = $holder->withAudience('one');
        $modified = $holder->withAudience('other');

        // Act
        $withSame = $original->isAudienceChanged($same);
        $withDiferent = $original->isAudienceChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientAllowedAudiencesAudienceAccessorUnitTest
{
    use TrustedClientAllowedAudiencesAudienceAccessor;
}
